        loadEventEndMs: Math.round(navEntry.loadEventEnd),
        responseStartMs: Math.round(navEntry.responseStart),
        responseEndMs: Math.round(navEntry.responseEnd),
        transferSize: navEntry.transferSize || 0,
        encodedBodySize: navEntry.encodedBodySize || 0,
        decodedBodySize: navEntry.decodedBodySize || 0,
